        assert_eq!(bus.read16(DMA3 + 10) & ENABLE_BIT, 0);
        assert_ne!(bus.irq.interrupt_flags & (1 << 11), 0);
    }

    #[test]
    fn decrement_and_fixed_address_control() {
        let mut bus = Bus::new(&[]);
        bus.write16(0x0300_0004, 0xAAAA);
        bus.write16(0x0300_0002, 0xBBBB);
