// args: rom replay frames out_prefix dump_every
use gba_emu::*;
fn main() {
    let a: Vec<String> = std::env::args().collect();
    let rom = std::fs::read(&a[1]).unwrap();
    let mut keys: Vec<(u32, u32)> = std::fs::read_to_string(&a[2]).unwrap().lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
        .map(|l| { let mut p = l.split_whitespace(); (p.next().unwrap().parse().unwrap(), u32::from_str_radix(p.next().unwrap(), 16).unwrap()) }).collect();
    keys.sort();
    let frames: u32 = a[3].parse().unwrap();
    let every: u32 = a[5].parse().unwrap();
    unsafe {
        emu_init();
        std::ptr::copy_nonoverlapping(rom.as_ptr(), emu_rom_buffer(), rom.len());
        emu_load_rom(rom.len() as i32);
        for f in 0..frames {
            for &(kf, k) in &keys { if kf == f { emu_set_keys(k); } }
            emu_run_frame();
            emu_audio_samples();
